<?php if(session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc(session()->getFlashdata('error')) ?></div><?php endif ?>
<?php if(session()->getFlashdata('success')): ?><div class="alert alert-success"><?= esc(session()->getFlashdata('success')) ?></div><?php endif ?><h2>Monitoring Durasi Sewa</h2><div class="row g-3"><?php foreach($rows as $r): ?><div class="col-md-6"><div class="card p-3"><strong>#<?= esc($r['id_sewa']) ?></strong><p>Jatuh tempo: <?= esc($r['waktu_selesai'] ?: $r['tanggal_kembali']) ?></p><h3 class="countdown" data-deadline="<?= esc($r['waktu_selesai'] ?: $r['tanggal_kembali'].' 23:59:59') ?>">Memuat...</h3><a href="<?= base_url('kasir/histori?status=berlangsung') ?>">Lihat histori aktif</a></div></div><?php endforeach ?></div><script>function updateCountdown(){document.querySelectorAll('.countdown').forEach(e=>{const t=new Date(e.dataset.deadline.replace(' ','T')).getTime()-Date.now();if(t<=0){e.textContent='TERLAMBAT';e.classList.add('text-danger');return;}const s=Math.floor(t/1000);e.textContent=Math.floor(s/86400)+' hari '+String(Math.floor(s%86400/3600)).padStart(2,'0')+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');});}updateCountdown();setInterval(updateCountdown,1000);</script><?= $this->endSection() ?>